section.mermaid:
flowchart LR
  T["tick"] --> A{"alive?"}
  A -- yes --> S{"stuck?"}
  A -- "no, 3 ticks" --> RA["repair: down, re-seat if the ticket is live"]
  S -- yes --> RS["repair 1 nudge, 2 escape and nudge, 3 retire and re-seat with resume"]
  S -- no --> X{"out of context?"}
  X -- yes --> RX["guard compacts; expired lease released; 3 cycles without progress is a finding"]
  X -- no --> C{"at capacity with open items?"}
  C -- yes --> RC["retry 3 ticks, then the down order, then seat and re-post"]
  RA --> F["finding on the orchestrator lane and the health line"]
  RS --> F
  RX --> F
  RC --> F
